import random
import time

class Stalker:
    def __init__(self, target, stalker_name="Stalker Bot"):
        self.target = target
        self.stalker_name = stalker_name
        self.messages = []

    def stalk(self):
        while True:
            self.messages.append(f"{self.stalker_name} sees {self.target}...")
            time.sleep(random.randint(1, 5))  # Simulate stalking behaviour
            print(self.messages[-1])

    def harass(self):
        while True:
            self.messages.append(f"{self.stalker_name} is concerned about {self.target}...")
            time.sleep(random.randint(1, 3))  # Simulate harassment
            print(self.messages[-1])

    def report(self):
        print(f"You have been reported by {self.stalker_name}!")

    def display_messages(self):
        if self.messages:
            for message in self.messages:
                print(message)
        else:
            print("No activity detected.")


def main():
    target = input("Enter the name of the target: ")

    stalker = Stalker(target)
    print(f"Stalker named {stalker.stalker_name} has been activated for {target}")

    while True:
        action = input("What would you like to do?\n"
                       "1. Start Stalking\n"
                       "2. Start Harassment\n"
                       "3. Display Messages\n"
                       "4. Exit\n"
                       "> ")

        if action == "1":
            stalker.stalk()
        elif action == "2":
            stalker.harass()
        elif action == "3":
            stalker.display_messages()
        elif action == "4":
            print("Exiting program...")
            break
        else:
            print("Invalid action. Please try again.")

if __name__ == "__main__":
    main()

